solution.solution.cpp:
class Date
{
public:
    Date(int year, int month, int day);
    explicit Date(int year);

    static bool isLeapYear(int year);

    int year() const { return m_year; }
    int month() const { return m_month; }
    int day() const { return m_day; }

private:
    int m_year{};
    int m_month{ 1 };
    int m_day{ 1 };
};

bool Date::isLeapYear(int year)
{
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

Date::Date(int year, int month, int day)
    : m_year{ year }, m_month{ month >= 1 && month <= 12 ? month : 1 }
{
    constexpr int lengths[]{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    int length{ lengths[m_month - 1] };
    if (m_month == 2 && isLeapYear(year))
    {
        length = 29;
    }
    m_day = (day >= 1 && day <= length) ? day : 1;
}

Date::Date(int year) : Date{ year, 1, 1 }
{
}

unitTests:
TEST("a normal date") { const Date d{ 2026, 11, 12 }; CHECK_EQ(d.year(), 2026); CHECK_EQ(d.month(), 11); CHECK_EQ(d.day(), 12); }
TEST("bad months become 1") { CHECK_EQ(Date(2026, 13, 5).month(), 1); CHECK_EQ(Date(2026, 0, 5).month(), 1); }
TEST("bad days become 1") { CHECK_EQ(Date(2026, 4, 31).day(), 1); CHECK_EQ(Date(2026, 4, 0).day(), 1); CHECK_EQ(Date(2026, 4, 30).day(), 30); }
TEST("February and leap years") { CHECK_EQ(Date(2024, 2, 29).day(), 29); CHECK_EQ(Date(2023, 2, 29).day(), 1); CHECK_EQ(Date(1900, 2, 29).day(), 1); CHECK_EQ(Date(2000, 2, 29).day(), 29); }
TEST("year-only constructor") { const Date d{ 1999 }; CHECK_EQ(d.year(), 1999); CHECK_EQ(d.month(), 1); CHECK_EQ(d.day(), 1); }
TEST("isLeapYear") { CHECK(Date::isLeapYear(2024)); CHECK(!Date::isLeapYear(2023)); CHECK(!Date::isLeapYear(1900)); CHECK(Date::isLeapYear(2000)); }

